using System.Security.Claims; using HabitFlow.Application; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Mvc;
namespace HabitFlow.Web.Controllers;
public class AuthController(AuthService auth):Controller{[HttpGet("login")]public IActionResult Login()=>View(); [HttpGet("register")]public IActionResult Register()=>View(); [HttpPost("register")][ValidateAntiForgeryToken]public async Task<IActionResult> Register(string name,string email,string password){var r=await auth.RegisterAsync(name,email,password); if(!r.Succeeded){ViewBag.Error=r.Error?.Message; return View();} await SignIn(r.Value!); return RedirectToAction("Index","Dashboard");} [HttpPost("logout")][ValidateAntiForgeryToken]public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync(); return RedirectToAction("Index","Home");} private async Task SignIn(HabitFlow.Domain.User u){var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Name),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role)}; await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)));}}
